 function productCard(p,t,i){const tag=t.categorySlug==="clothing-fashion"?(i===0?"FEATURED":t.key==="streetwear-sneaker-store"?"LATEST DROP":"THE EDIT"):(i===0?"POPULAR":"FRESH PICK");return '<article class="hf-shop-product"><div class="hf-shop-product-image"><img loading="lazy" src="'+photo(p[4])+'" alt="'+esc(p[0])+'"><span class="hf-shop-product-tag">'+tag+'</span><button type="button" class="hf-shop-add" data-add="'+i+'" aria-label="Add '+esc(p[0])+'">+</button></div><div class="hf-shop-product-info"><small>'+esc(p[1])+'</small><strong>'+esc(p[0])+'</strong><div><b>'+esc(p[2])+'</b><span>'+esc(p[3])+'</span></div></div></article>'; }
