 async function updateBrowserPreviewLinks(templateKey){
  const links=[$("wpTemplateBrowserTop"),$("wpTemplateBrowserBottom")].filter(Boolean);
  links.forEach(link=>{link.href="#";link.setAttribute("aria-disabled","true");link.removeAttribute("data-preview-ready");});
  try{
   const api=window.WPNeonBuilderApi;
   if(!api?.ensureWebsite||!api?.publishShowcaseWebsite)throw new Error("The live website publishing API did not load. Refresh the workspace.");
   const selected=templates.find(item=>item.key===templateKey);
   if(selected?.previewUrl){const href=selected.previewUrl;links.forEach(link=>{link.href=href;link.dataset.previewReady="true";link.removeAttribute("aria-disabled");});const address=$("wpTemplateAddress");if(address)address.textContent=href;const connection=$("wpTemplateConnection");if(connection){connection.textContent="LIVE PREVIEW · READY";connection.dataset.state="connected";connection.title="Responsive showcase website is deployed and available.";}if(templates[active]?.key===templateKey){const host=$("wpStorefront");if(host)host.innerHTML='<iframe class="hf-wpt-live-preview-frame" title="'+esc(selected.name)+' live preview" src="'+esc(href)+'" loading="eager"></iframe>';}return;}
   const website=await api.ensureWebsite(templateKey,selected?.name||templateKey);
   const targetCategory=["medicine-pharmacy","hospital-healthcare","real-estate-property","restaurant-food","beauty-salon","automotive-services","professional-services","construction-interior","portfolio-agency","education-training","fitness-gym","events-weddings"].includes(selected?.categorySlug);
   const liveWebsite=targetCategory?await api.publishShowcaseWebsite(website):website;
   // Keep the read-only showcase preview context. The preview auth gate now
   // reads the nested Neon session correctly for the signed-in admin.
   const href="../storefront.html?site="+encodeURIComponent(liveWebsite.slug)+"&preview=1";
   links.forEach(link=>{link.href=href;link.dataset.previewReady="true";link.removeAttribute("aria-disabled");});
   const address=$("wpTemplateAddress");if(address)address.textContent=location.origin+"/storefront.html?site="+liveWebsite.slug;
   const connection=$("wpTemplateConnection");
   if(connection){connection.textContent=targetCategory?"PUBLIC SHOWCASE · LIVE":"NEON CONNECTED · PRIVATE PREVIEW";connection.dataset.state="connected";connection.title=targetCategory?"Published showcase website; sample content only, checkout and enquiries disabled.":"Private draft preview; this category's publish state is unchanged.";}
   if(templates[active]?.key!==templateKey)return;
   if(["medicine-pharmacy","hospital-healthcare","real-estate-property","restaurant-food","beauty-salon","automotive-services","professional-services","construction-interior","portfolio-agency","education-training","fitness-gym","events-weddings"].includes(selected?.categorySlug)){
    const host=$("wpStorefront");
    if(host){host.dataset.template=templateKey;host.innerHTML='<iframe class="hf-wpt-live-preview-frame" title="'+esc(selected.name)+' live storefront preview" src="'+href+'" loading="eager" referrerpolicy="same-origin"></iframe>';}
   }
  }catch(error){
   console.warn("Live showcase preview is not ready yet.",error);
   const selected=templates.find(item=>item.key===templateKey);
   const connection=$("wpTemplateConnection");
   if(connection){connection.textContent="LOCAL PREVIEW · LIVE LINK UNAVAILABLE";connection.dataset.state="offline";connection.title=String(error?.message||error);}
   const address=$("wpTemplateAddress");if(address)address.textContent="Local design preview active · public website connection pending";
   // Preserve the already-rendered local design when the live preview service is unavailable.
  }
 }

